import java.util.*;

class Solution {
    public int sumFirstN(int n) {
        return sumUntil(n, 0);
    }

    private int sumUntil(int n, int currentSum) {
        if (n <= 0) {
            return currentSum;
        }
        return sumUntil(n - 1, currentSum + n);
    }
}

import java.util.*;

class Solution {
    public int sumFirstN(int n) {
        if (n <= 0) {
            return 0;
        }
        return n + sumFirstN(n - 1);
    }
}

import java.util.*;

class Solution {
    public int sumFirstN(int n) {
        int sum = 0;
        for (int value = 1; value <= n; value++) {
            sum += value;
        }
        return sum;
    }
}

